import{_ as o,o as e,c as r,ag as a}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"🔬 科学快报 | 2026年9月26日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-26.md","filePath":"science-log/src/reconstructed/2026-09-26.md"}'),n={name:"science-log/src/reconstructed/2026-09-26.md"};function s(i,t,u,g,q,l){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="🔬-科学快报-2026年9月26日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月26日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月26日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月26日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。当日为周六（2026-09-26），Nature / Science / PNAS 均无刊出（CrossRef 命中 0），故科学 5 篇取自最近的出版窗口 <strong>2026-09-21 ~ 2026-09-26</strong>，并逐条标注实际出版日。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202609260000 TO 202609262359]</code>（cs.AI，命中 30 篇）｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-一个产甲烷菌水解酶-看穿-了古菌肽聚糖的结构" tabindex="-1">🧬 一个产甲烷菌水解酶&quot;看穿&quot;了古菌肽聚糖的结构 <a class="header-anchor" href="#🧬-一个产甲烷菌水解酶-看穿-了古菌肽聚糖的结构" aria-label="Permalink to &quot;🧬 一个产甲烷菌水解酶&quot;看穿&quot;了古菌肽聚糖的结构&quot;">​</a></h3><p><strong>A methanogen hydrolase reveals the structure of archaeal peptidoglycan</strong><em>Nature（2026-09-23）</em></p><p>细菌的细胞壁由肽聚糖（murein）编织，而古菌长期被认为用假肽聚糖（pseudomurein）等替代——两者是否同源、结构如何，一直是微生物学家争论的悬案。该研究（Robert Smith、Nika Pende、Aline Rifflet 等 23 位作者）从一种产甲烷古菌中分离到能切割其细胞壁聚合物的水解酶，借这条&quot;分子手术刀&quot;反向解析出古菌肽聚糖的骨架与交联方式。意义在于：它把古菌细胞壁从&quot;结构黑箱&quot;变成可被酶学与结构手段攻克的对象，为理解生命三域分化中细胞壁的演化路径提供了直接的分子证据。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-11028-y" target="_blank" rel="noreferrer">10.1038/s41586-026-11028-y</a></p><h3 id="💡-cvd-生长-1h-mos2-双层里的-堆叠诱导-直接带隙" tabindex="-1">💡 CVD 生长 1H-MoS₂ 双层里的&quot;堆叠诱导&quot;直接带隙 <a class="header-anchor" href="#💡-cvd-生长-1h-mos2-双层里的-堆叠诱导-直接带隙" aria-label="Permalink to &quot;💡 CVD 生长 1H-MoS₂ 双层里的&quot;堆叠诱导&quot;直接带隙&quot;">​</a></h3><p><strong>Stacking-induced direct band gap in CVD-grown 1H MoS2 bilayers</strong><em>Nature（2026-09-23）</em></p><p>单层二硫化钼（MoS₂）因直接带隙而发光，但一旦叠成双层，层间耦合通常把带隙压成&quot;间接&quot;，发光骤降——这是二维光电子学的经典困境。Tilo H. Yang、I-Tong Chen、Min-Jia Zhang 等（19 位作者）在化学气相沉积（CVD）生长的 <strong>1H（菱形 3R 型）堆叠</strong>双层中，观测到由堆叠方式而非层数决定的<strong>直接带隙</strong>。这打破了&quot;双层必间接&quot;的经验规则，说明堆叠序（stacking order）是一个可独立调控的电子结构旋钮，指向无需应变或电场就能发光的双层二维器件。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-11069-3" target="_blank" rel="noreferrer">10.1038/s41586-026-11069-3</a></p><h3 id="⚗️-拥抱-三重态氮宾-把芳环的碳直接换成氮" tabindex="-1">⚗️ 拥抱&quot;三重态氮宾&quot;：把芳环的碳直接换成氮 <a class="header-anchor" href="#⚗️-拥抱-三重态氮宾-把芳环的碳直接换成氮" aria-label="Permalink to &quot;⚗️ 拥抱&quot;三重态氮宾&quot;：把芳环的碳直接换成氮&quot;">​</a></h3><p><strong>Embracing triplet nitrenes for C-to-N replacement of complex bicyclic (hetero)aryl azides</strong><em>Science（2026-09-24）</em></p><p>把芳环上的一个碳原子换成氮（&quot;单原子替换&quot;），能快速得到药物化学里难得的含氮杂环骨架，但现有方法对底物挑剔、且依赖苛刻氧化条件。主流路线走<strong>单重态（singlet）氮宾</strong>的价键异构，问题在于它常被竞争性的<strong>系间窜越（intersystem crossing）</strong>&quot;偷走&quot;，掉进反应性不同的三重态而中止。Dong-Il Park 等（6 位作者）反其道而行——<strong>主动利用三重态芳基氮宾</strong>，在萘、蒽、吲哚、苯并呋喃、苯并噻吩、吲唑、苯并异噻唑等一系列双环（杂）芳烃上完成苯环碳→氮的替换。反应条件温和，因此能用于<strong>复杂而敏感天然产物</strong>的后期修饰，把&quot;被嫌弃的副路线&quot;变成了主路线。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aef3511" target="_blank" rel="noreferrer">10.1126/science.aef3511</a></p><h3 id="🔬-用电子叠层成像-数清-金属里的每一个氢原子" tabindex="-1">🔬 用电子叠层成像&quot;数清&quot;金属里的每一个氢原子 <a class="header-anchor" href="#🔬-用电子叠层成像-数清-金属里的每一个氢原子" aria-label="Permalink to &quot;🔬 用电子叠层成像&quot;数清&quot;金属里的每一个氢原子&quot;">​</a></h3><p><strong>Atomic-scale quantification of hydrogen in metal hydrides by electron ptychography</strong><em>Science Advances（2026-09-25）</em></p><p>氢是最轻的元素：散射电子极弱、在晶格里四处游走，传统透射电镜几乎&quot;看不见&quot;它，导致储氢材料中氢的占位与分布长期不可及。Pengcheng Li 等（9 位作者）用<strong>能量过滤多切片电子叠层成像（energy-filtered multislice electron ptychography, MEP）</strong>，在一枚<strong>高熵合金（HEA）氢化物</strong>里实现了氢的原子分辨成像与定量分析，解析出此前无法看到的细节（包括皮米级氢位移）。它把&quot;看不见的轻元素&quot;纳入定量结构解析，对理解储氢、氢脆与金属—氢相互作用是方法论级的突破。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aed5872" target="_blank" rel="noreferrer">10.1126/sciadv.aed5872</a></p><h3 id="🌀-光学孤子自组织途中-短暂发疯-的瞬态混沌" tabindex="-1">🌀 光学孤子自组织途中&quot;短暂发疯&quot;的瞬态混沌 <a class="header-anchor" href="#🌀-光学孤子自组织途中-短暂发疯-的瞬态混沌" aria-label="Permalink to &quot;🌀 光学孤子自组织途中&quot;短暂发疯&quot;的瞬态混沌&quot;">​</a></h3><p><strong>Transient chaos in the self-organization of dissipative optical solitons</strong><em>PNAS（2026-09-25）</em></p><p>瞬态混沌是复杂动力学的标志：系统在落向稳定吸引子之前，先被&quot;混沌鞍（chaotic saddle）&quot;短暂俘获，表现出丰富却转瞬即逝的乱象。它难以实时捕捉，因而物理机制长期蒙尘。Kun Chen 等（9 位作者）在<strong>锁模光纤激光器</strong>中，首次实验记录到<strong>耗散光学孤子自组织</strong>过程中的瞬态混沌：通过<strong>单次测量（single-shot）<strong>重建相空间轨迹，定量出关键动力学不变量，证实其底层是</strong>确定性</strong>动力学（而非噪声）。这把&quot;随机表象&quot;归因到确定性结构，为非线性光学与复杂系统提供了可复现的实验模板。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2624826123" target="_blank" rel="noreferrer">10.1073/pnas.2624826123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧠-承诺-弃答回路-语言模型为何-硬答-而非说-不知道" tabindex="-1">🧠 承诺-弃答回路：语言模型为何&quot;硬答&quot;而非说&quot;不知道&quot; <a class="header-anchor" href="#🧠-承诺-弃答回路-语言模型为何-硬答-而非说-不知道" aria-label="Permalink to &quot;🧠 承诺-弃答回路：语言模型为何&quot;硬答&quot;而非说&quot;不知道&quot;&quot;">​</a></h3><p><strong>The Commit-Abstain Circuit: Why Language Models Hallucinate Instead of Abstaining</strong><em>arXiv（2026-09-26）</em></p><p>模型在信息不足时仍给出自信答案，是幻觉的核心。此前工作多从&quot;检测/弃答&quot;外部机制入手，却回避了模型&quot;内部如何决定要答还是要弃&quot;。Vy Nguyen 等（8 位作者）用<strong>因果门控（causal gating）<strong>做机制分析，在 5 大家族、10 个 3B–14B 模型、3 个基准上识别出一个稀疏且因果局部的</strong>承诺-弃答回路（Commit-Abstain Circuit, CAC）</strong>：注意力头与 MLP 子层中，前半段&quot;推承诺&quot;的组件不断累积作答倾向，后半段&quot;促弃答&quot;的组件才迟来地纠正——形成反复出现的&quot;<strong>累积却欠纠正（accumulate-yet-undercorrect）</strong>&quot;模式。这解释了幻觉为何是&quot;带内部信号的错误承诺&quot;，并给出了可直接干预的回路靶点。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.32964" target="_blank" rel="noreferrer">2609.32964</a></p><h3 id="🗂️-智能体记忆的认识论-从-记得多少-到-该不该信这次整合" tabindex="-1">🗂️ 智能体记忆的认识论：从&quot;记得多少&quot;到&quot;该不该信这次整合&quot; <a class="header-anchor" href="#🗂️-智能体记忆的认识论-从-记得多少-到-该不该信这次整合" aria-label="Permalink to &quot;🗂️ 智能体记忆的认识论：从&quot;记得多少&quot;到&quot;该不该信这次整合&quot;&quot;">​</a></h3><p><strong>The Epistemics of Agent Memory: Measuring, and Governing, the Consolidation Decision in Long-Horizon LLM Agents</strong><em>arXiv（2026-09-26）</em></p><p>长时程智能体必须把经验沉淀为持久记忆——保留、压缩、抽象成可复用技能，或遗忘。Sasank Annapureddy 等把&quot;整合决策（consolidation decision）&quot;本身当作研究对象，追问的不是&quot;记得多不多&quot;，而是&quot;这些整合决策好不好、可不可信&quot;。四阶段研究中，Phase 2 在 token 预算下学习&quot;何时提升经验、提升到哪个抽象层级&quot;，取得 <strong>+22.7% 任务成功率、7 倍压缩</strong>，但同时暴露两种失败模式（退化性遗忘、以及被作者命名为 λ-prevalence coupling 的分布漂移）。Phase 3 提出 <strong>ConsolidationBench</strong>。它把&quot;记忆治理&quot;从工程技巧提升为可度量的认识论问题。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.33013" target="_blank" rel="noreferrer">2609.33013</a></p><h3 id="🎮-gamesmith-用-合成游戏-把零和自博弈规模化" tabindex="-1">🎮 GameSmith：用&quot;合成游戏&quot;把零和自博弈规模化 <a class="header-anchor" href="#🎮-gamesmith-用-合成游戏-把零和自博弈规模化" aria-label="Permalink to &quot;🎮 GameSmith：用&quot;合成游戏&quot;把零和自博弈规模化&quot;">​</a></h3><p><strong>GameSmith: Scaling Zero-Sum Self-Play with Synthesised Games</strong><em>arXiv（2026-09-26）</em></p><p>在双人零和博弈上后训练，能提供<strong>可验证奖励</strong>且收益可迁移到通用推理，但既有流水线只靠少数手写游戏，且优势估计器绑死在这些游戏上——游戏供给与优势估计双双成为规模瓶颈。Weixian Waylon Li 等（7 位作者）提出 <strong>GameSmith</strong>：让 LLM 在&quot;奖励/观测/隐藏信息代码固定&quot;的模板内合成新游戏，每条游戏经<strong>种子配对重放 + 独立重实现</strong>双重验证，再扩展出编码/规则/尺寸变体，从三个 SPIRAL 模板得到 <strong>29 个家族、26 个新游戏、336 个验证变体</strong>；模型从更大的教师（Qwen3-32B）自博弈蒸馏、再用自博弈强化学习训练，配合新的优势估计器 <strong>CRAB</strong>。它把&quot;造游戏&quot;和&quot;评优势&quot;都变成可扩展的自动环节。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2610.13995" target="_blank" rel="noreferrer">2610.13995</a></p><h3 id="🤖-capex-把基础模型-蒸馏-成可部署的机器人策略" tabindex="-1">🤖 CAPEX：把基础模型&quot;蒸馏&quot;成可部署的机器人策略 <a class="header-anchor" href="#🤖-capex-把基础模型-蒸馏-成可部署的机器人策略" aria-label="Permalink to &quot;🤖 CAPEX：把基础模型&quot;蒸馏&quot;成可部署的机器人策略&quot;">​</a></h3><p><strong>CAPEX: Efficiently Distilling Foundation Model Behavior into Deployable Robot Policies</strong><em>arXiv（2026-09-26）</em></p><p>机器人学习长期依赖人类遥操作演示，采集不直观、难扩展、还本质上异步。Shivam Aarya 等（9 位作者）探索另一条路：<strong>把通用多模态基础模型的物理行为&quot;蒸馏&quot;进可部署的机器人策略</strong>，即让基础模型自己充当&quot;自主演示者&quot;。难点在于——能力足够强的模型虽能零样本生成成功的操作轨迹，但<strong>物理执行时反复调用它们既慢又贵</strong>。为此他们提出 <strong>CAPEX</strong>：一个**经验条件化（experience-conditioned）**的演示采集框架，用先前执行经验引导后续演示生成，在保证可用性的同时摊薄高昂的模型调用成本。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.33007" target="_blank" rel="noreferrer">2609.33007</a></p><h3 id="🛠️-sre-marathon-把-站点可靠性-从单次排障变成不间断长跑" tabindex="-1">🛠️ SRE-Marathon：把&quot;站点可靠性&quot;从单次排障变成不间断长跑 <a class="header-anchor" href="#🛠️-sre-marathon-把-站点可靠性-从单次排障变成不间断长跑" aria-label="Permalink to &quot;🛠️ SRE-Marathon：把&quot;站点可靠性&quot;从单次排障变成不间断长跑&quot;">​</a></h3><p><strong>SRE-Marathon: A Continuous, Change-Driven Benchmark for Autonomous Site Reliability Agents</strong><em>arXiv（2026-09-26）</em></p><p>现有 SRE（站点可靠性工程）智能体基准大多是&quot;情景式&quot;的：注入一个故障、给一个事件、评一次分。真实生产却不然——告警嘈杂、事件在时间上重叠、且常始于代码或配置变更。Yifang Tian 等（7 位作者）提出 <strong>SRE-Marathon</strong>：面向<strong>长时程、连续</strong>的 SRE 运行，智能体按固定节拍被唤起，面对<strong>累积的告警历史</strong>与<strong>持久工作区</strong>，同时操作一个真实的两可用区 Kubernetes 部署，而&quot;故障编排器&quot;按<strong>播种、经生产校准</strong>的计划注入重叠故障。改动用与修复同一条构建管线推送，每次运行被录成**封闭包（sealed bundle）**计分。它把评测从&quot;会不会排一个障&quot;推向&quot;能否长期值守并扛住变更引发的连锁&quot;。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.33023" target="_blank" rel="noreferrer">2609.33023</a></p><blockquote><p>📅 日期：2026-09-26 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 期号：（第 ? 期 · 事后重建版）</p></blockquote>',45)])])}const p=o(n,[["render",s]]);export{c as __pageData,p as default};
